// ── BEFORE: smelly function ─────────────────────────────────────
function process(u, t) {
  // check if valid
  if (u.age >= 18 && !u.banned && t === 'premium') {
    let x = u.balance * 0.9;   // 10% discount, magic number
    if (x > 1000) x = 1000;    // cap, magic number
    return x;
  }
  return u.balance;
}
console.log(process({ age: 25, banned: false, balance: 1200 }, 'premium')); // 1000

// ── AFTER: applied Extract Variable, Rename, Replace Magic Number ─
const PREMIUM_DISCOUNT_RATE = 0.1;
const MAX_DISCOUNT_AMOUNT   = 1000;

function isEligibleForDiscount(user, tierType) {
  return user.age >= 18 && !user.banned && tierType === 'premium';
}

function calcDiscount(balance) {
  const discount = balance * PREMIUM_DISCOUNT_RATE;
  return Math.min(discount, MAX_DISCOUNT_AMOUNT);
}

function calcFinalBalance(user, tierType) {
  if (!isEligibleForDiscount(user, tierType)) return user.balance;
  return user.balance - calcDiscount(user.balance);
}
console.log(calcFinalBalance({ age: 25, banned: false, balance: 1200 }, 'premium')); // 1000
console.log(calcFinalBalance({ age: 15, banned: false, balance: 1200 }, 'premium')); // 1200

// ── Decompose Conditional → Replace with Strategy map ──────────
// BEFORE
function getShipping(type) {
  if (type === 'express') return 25;
  if (type === 'standard') return 10;
  if (type === 'free') return 0;
  return 15; // default
}
// AFTER — adding a new type = one new entry, function body untouched
const SHIPPING_RATES = { express: 25, standard: 10, free: 0 };
const DEFAULT_RATE   = 15;
const getShippingRate = (type) => SHIPPING_RATES[type] ?? DEFAULT_RATE;
console.log(getShippingRate('express'));  // 25
console.log(getShippingRate('drone'));    // 15

