function createOrder({ customerId, productId, quantity, discountCode, shippingType }) {
  // destructuring makes callsite self-documenting
}
createOrder({ customerId: 1, productId: 42, quantity: 2, discountCode: 'SAVE10', shippingType: 'express' });

