// ── Encapsulate Field ────────────────────────────────────────────
// BEFORE — direct field access everywhere, can't add validation
class Account {
  constructor(bal) { this.balance = bal; }
}
const a = new Account(100);
a.balance = -500; // silent bad state!

// AFTER — encapsulated; validation in one place
class AccountSafe {
  #balance;
  constructor(bal) { this.#balance = bal; }
  get balance() { return this.#balance; }
  set balance(v) {
    if (v < 0) throw new RangeError('Balance cannot be negative');
    this.#balance = v;
  }
}
const b = new AccountSafe(100);
try { b.balance = -500; } catch (e) { console.log(e.message); } // Balance cannot be negative
console.log(b.balance); // 100
